#include <bits/stdc++.h>
using namespace std;

// Build KMP automaton for pattern s
vector<array<int,2>> build_automaton(const string &s) {
    int m = s.size();
    vector<int> pi(m,0);
    for (int i=1;i<m;i++) {
        int j = pi[i-1];
        while (j>0 && s[i]!=s[j]) j = pi[j-1];
        if (s[i]==s[j]) j++;
        pi[i]=j;
    }
    vector<array<int,2>> aut(m+1);
    for (int state=0; state<=m; ++state) {
        for (int c=0;c<2;c++) {
            char ch = char('0'+c);
            if (state==m) {
                int j = pi[m-1];
                while (j>0 && ch!=s[j]) j = pi[j-1];
                if (ch==s[j]) j++;
                aut[state][c]=j;
            } else {
                int j = state;
                while (j>0 && ch!=s[j]) j = pi[j-1];
                if (ch==s[j]) j++;
                aut[state][c]=j;
            }
        }
    }
    return aut;
}

// Count strings of length n that avoid s as substring
long long count_avoid(int n, const string &s) {
    int m = s.size();
    auto aut = build_automaton(s);
    vector<long long> dp(m+1), ndp(m+1);
    dp[0]=1;
    for (int pos=0; pos<n; ++pos) {
        fill(ndp.begin(), ndp.end(), 0);
        for (int st=0; st<=m; ++st) {
            if (!dp[st]) continue;
            for (int c=0;c<2;c++) {
                int ns = aut[st][c];
                if (ns==m) continue; // substring found, forbidden
                ndp[ns]+=dp[st];
            }
        }
        dp.swap(ndp);
    }
    long long res=0;
    for (int st=0; st<m; ++st) res+=dp[st];
    return res;
}

// Check if s occurs in any cyclic shift of t
bool contains_cyclic(const string &t, const string &s) {
    int n = t.size();
    int m = s.size();
    string tt = t + t;
    // KMP search s in tt, but only positions < n
    vector<int> pi(m,0);
    for (int i=1;i<m;i++) {
        int j = pi[i-1];
        while (j>0 && s[i]!=s[j]) j = pi[j-1];
        if (s[i]==s[j]) j++;
        pi[i]=j;
    }
    int j=0;
    for (int i=0;i<(int)tt.size();++i) {
        while (j>0 && tt[i]!=s[j]) j = pi[j-1];
        if (tt[i]==s[j]) j++;
        if (j==m) {
            int start = i-m+1;
            if (start < n) return true;
            j = pi[j-1];
        }
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    if (!(cin>>n)) return 0;
    cin>>s;
    int m = s.size();
    long long total = 1LL<<n;
    long long avoid = count_avoid(n,s);
    long long ans = total - avoid;

    // adjust for cyclic condition: we counted linear strings containing s,
    // but need cyclic strings where some cyclic shift contains s.
    // For small n (<=20) brute-force to correct; for larger n assume linear == cyclic.
    if (n<=20) {
        long long brute=0;
        for (long long mask=0; mask<(1LL<<n); ++mask) {
            string t(n,'0');
            for (int i=0;i<n;i++) if (mask&(1LL<<i)) t[i]='1';
            if (contains_cyclic(t,s)) brute++;
        }
        ans = brute;
    }

    cout<<ans<<"\n";
    return 0;
}

