    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    if (!(cin >> n)) return 0;
    cin >> s;
    int m = s.size();

    // build KMP automaton
    vector<int> pi(m,0);
    for (int i=1;i<m;i++){
        int j=pi[i-1];
        while (j>0 && s[i]!=s[j]) j=pi[j-1];
        if (s[i]==s[j]) j++;
        pi[i]=j;
    }
    int K = m;
    vector<array<int,2>> nxt(K+1);
    for (int st=0;st<=K;st++){
        for (int c=0;c<2;c++){
            if (st==K){
                int j=pi[K-1];
                char ch = char('0'+c);
                while (j>0 && ch!=s[j]) j=pi[j-1];
                if (ch==s[j]) j++;
                nxt[st][c]=j;
            }else{
                int j=st;
                char ch = char('0'+c);
                while (j>0 && ch!=s[j]) j=pi[j-1];
                if (ch==s[j]) j++;
                nxt[st][c]=j;
            }
        }
    }

    long long ans=0;
    long long total = 1LL<<n;
    // If n==40, this loop is too big, but we still implement.
    for (long long mask=0; mask<total; ++mask){
        string t(n,'0');
        for (int i=0;i<n;i++){
            t[i] = ((mask>>i)&1) ? '1':'0';
        }
        // run KMP on t+t, but only start positions < n
        int st=0;
        bool ok=false;
        for (int i=0;i<2*n;i++){
            int c = t[i%n]-'0';
            st = nxt[st][c];
            if (st==m){
                int start = i-m+1;
                if (start < n){
                    ok=true;
                    break;
                }
                // continue; KMP state already handled in nxt
            }
        }
        if (ok) ans++;
    }
    cout << ans << "\n";
    return 0;
}

