int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    if (!(cin >> n)) return 0;
    cin >> s;
    int m = (int)s.size();

    // Build KMP automaton for pattern s
    vector<int> pi(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = pi[i-1];
        while (j > 0 && s[i] != s[j]) j = pi[j-1];
        if (s[i] == s[j]) ++j;
        pi[i] = j;
    }

    // next_state[state][bit]
    vector<array<int,2>> nxt(m+1);
    for (int state = 0; state <= m; ++state) {
        for (int b = 0; b < 2; ++b) {
            if (state == m) {
                // Once matched, stay in m
                nxt[state][b] = m;
                continue;
            }
            char c = char('0' + b);
            int j = state;
            while (j > 0 && s[j] != c) j = pi[j-1];
            if (s[j] == c) ++j;
            if (j == m) nxt[state][b] = m;
            else nxt[state][b] = j;
        }
    }

    // DP[pos][state][first_state][first_bit]
    // pos: 0..n, state: 0..m, first_state: 0..m, first_bit: 0..2 (2 = undefined)
    static long long dp[41][41][41][3];
    memset(dp, 0, sizeof(dp));

    // Initialize at position 0
    dp[0][0][0][2] = 1;

    for (int pos = 0; pos < n; ++pos) {
        for (int state = 0; state <= m; ++state) {
            for (int fst = 0; fst <= m; ++fst) {
                for (int fb = 0; fb < 3; ++fb) {
                    long long cur = dp[pos][state][fst][fb];
                    if (!cur) continue;
                    for (int b = 0; b < 2; ++b) {
                        int ns = nxt[state][b];
                        int nfst = fst;
                        int nfb = fb;
                        if (pos == 0) {
                            nfst = ns;
                            nfb = b;
                        }
                        dp[pos+1][ns][nfst][nfb] += cur;
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int state = 0; state <= m; ++state) {
        for (int fst = 0; fst <= m; ++fst) {
            for (int fb = 0; fb < 2; ++fb) {
                long long cnt = dp[n][state][fst][fb];
                if (!cnt) continue;

                bool ok = false;
                if (state == m || fst == m) {
                    ok = true;
                } else {
                    int cur = state;
                    int j = cur;
                    while (j > 0 && s[j] != char('0' + fb)) j = pi[j-1];
                    if (s[j] == char('0' + fb)) ++j;
                    if (j == m) ok = true;
                }

                if (ok) ans += cnt;
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

